"""One-click local VPS Manager replacement. NO SSH, PAPER or trading operations.

The existing trusted EXE verifies a GitHub release asset and launches a
native Windows helper that waits for this process to quit before replacing it.
A running EXE never attempts to replace itself on Windows.
"""
from __future__ import annotations

import os
from pathlib import Path
import subprocess
import sys

from research.local_replay_viewer.desktop_update import (
    find_asset, fetch_verified, UpdateBlocked,
)

NAME = "BybitScanner-VPS-Manager.exe"

# This is generated by the already-installed program; not downloaded code.
# Source and destination are narrow owner-owned paths. Hash is checked again
# at the actual replacement point. No Powershell script ever touches the VPS.
HELPER = r"""
param(
  [Parameter(Mandatory=$true)][string]$Source,
  [Parameter(Mandatory=$true)][string]$Target,
  [Parameter(Mandatory=$true)][string]$Digest,
  [Parameter(Mandatory=$true)][int]$OldPid
)
$ErrorActionPreference = 'Stop'
$root = Join-Path $env:LOCALAPPDATA 'BybitScanner\VPSManager'
$root = [IO.Path]::GetFullPath($root).TrimEnd('\')
$sourceFile = [IO.Path]::GetFullPath($Source)
$targetFile = [IO.Path]::GetFullPath($Target)
$expectedPrefix = "$root\"
if (-not $sourceFile.StartsWith($expectedPrefix, [StringComparison]::OrdinalIgnoreCase) -or
    -not $targetFile.StartsWith($expectedPrefix, [StringComparison]::OrdinalIgnoreCase) -or
    [IO.Path]::GetFileName($sourceFile) -ne 'BybitScanner-VPS-Manager.exe' -or
    [IO.Path]::GetFileName($targetFile) -ne 'BybitScanner-VPS-Manager.exe' -or
    -not [IO.Path]::GetDirectoryName($sourceFile).EndsWith('\'+'.desktop-update-'+$env:DESKTOP_UPDATE_SHA,
        [StringComparison]::OrdinalIgnoreCase)) {
  throw 'UNTRUSTED_MANAGER_UPDATE_PATHS'
}
if ($Digest -notmatch '^[0-9a-f]{64}$' -or
    (Get-FileHash -LiteralPath $sourceFile -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Digest) {
  throw 'MANAGER_UPDATE_HASH_UNPROVEN'
}
try {
  Wait-Process -Id $OldPid -Timeout 30 -ErrorAction SilentlyContinue
} catch { throw 'MANAGER_DID_NOT_EXIT' }
if (Get-Process -Id $OldPid -ErrorAction SilentlyContinue) {
  throw 'MANAGER_PROCESS_STILL_ACTIVE'
}
$backup = Join-Path ([IO.Path]::GetDirectoryName($targetFile)) ('BybitScanner-VPS-Manager.previous-' + [guid]::NewGuid().ToString('N') + '.exe')
Move-Item -LiteralPath $targetFile -Destination $backup -ErrorAction Stop
try {
  Move-Item -LiteralPath $sourceFile -Destination $targetFile -ErrorAction Stop
  Start-Process -FilePath $targetFile -ErrorAction Stop
} catch {
  if (Test-Path -LiteralPath $targetFile) {
    Move-Item -LiteralPath $targetFile -Destination ($targetFile + '.failed') -ErrorAction SilentlyContinue
  }
  if (-not (Test-Path -LiteralPath $targetFile)) {
    Move-Item -LiteralPath $backup -Destination $targetFile -ErrorAction Stop
  }
  throw
}
"""


def _installed_path() -> Path:
    if not getattr(sys, "frozen", False) or os.name != "nt":
        raise UpdateBlocked("manager_update_requires_installed_windows_exe")
    path = Path(sys.executable).resolve()
    appdata = Path(os.environ.get("LOCALAPPDATA", "")).resolve()
    expected = appdata / "BybitScanner" / "VPSManager"
    if (not expected.is_dir() or not path.is_relative_to(expected)
            or path.name.lower() != NAME.lower()):
        raise UpdateBlocked("manager_update_requires_trusted_install")
    return path


def stage_manager() -> str:
    """Called only on owner click, never in a timer or startup hook."""
    current = _installed_path()
    release = find_asset("manager")
    marker = Path(getattr(sys, "_MEIPASS", "")) / "desktop-build-sha.txt"
    if marker.is_file() and marker.read_text(encoding="ascii").strip() == release.sha:
        raise UpdateBlocked("manager_already_current")
    stage_dir = current.parent / (".desktop-update-" + release.sha)
    stage_dir.mkdir(exist_ok=True)
    executable = stage_dir / NAME
    if executable.exists():
        raise UpdateBlocked("prior_update_stage_present; do_not_retry_automatically")
    fetch_verified(release, executable)
    helper = stage_dir / "apply-manager-update.ps1"
    if helper.exists():
        raise UpdateBlocked("prior_update_helper_present")
    helper.write_text(HELPER, encoding="ascii")
    powershell = (Path(os.environ.get("SystemRoot", "C:\\Windows"))
                  / "System32" / "WindowsPowerShell" / "v1.0" / "powershell.exe")
    if not powershell.is_file():
        raise UpdateBlocked("trusted_powershell_unavailable")
    environment = os.environ.copy()
    environment["DESKTOP_UPDATE_SHA"] = release.sha
    try:
        subprocess.Popen(
            [str(powershell), "-NoProfile", "-NonInteractive",
             "-ExecutionPolicy", "Bypass", "-File", str(helper),
             "-Source", str(executable), "-Target", str(current),
             "-Digest", release.digest, "-OldPid", str(os.getpid())],
            close_fds=True, env=environment,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
    except OSError as exc:
        raise UpdateBlocked("verified_updater_launch_failed") from exc
    return "VERIFIED_MANAGER_UPDATE_HANDOFF"
